    override val shape: String get() = "MarginAlert"
    override fun equals(other: Any?) = other is Keyed && other.shape == shape && other.key == key
    override fun hashCode() = 31 * shape.hashCode() + key.hashCode()
}

data class Administrator(
    override val key: StoreKey,
    val name: String,
    val role: String,
    val vendorAssignments: List<Ref<VendorAssignment>>,
) : Ref<Staff> {
    override val shape: String get() = "Staff"
    override fun equals(other: Any?) = other is Keyed && other.shape == shape && other.key == key
    override fun hashCode() = 31 * shape.hashCode() + key.hashCode()
}

data class ThinMargin(
    override val key: StoreKey,
    override val vendor: Ref<Vendor>,
    override val name: String,
    override val price: BigDecimal,
    override val cost: BigDecimal?,
    override val margin: BigDecimal?,
    override val marginAlerts: List<Ref<MarginAlert>>,
) : Ref<Product>, ThinMarginForStaff {
    override val shape: String get() = "Product"
    override fun equals(other: Any?) = other is Keyed && other.shape == shape && other.key == key
    override fun hashCode() = 31 * shape.hashCode() + key.hashCode()
}

// ── what a viewer receives (Reference §22, "The actor"): one interface per viewer shape per shape
// with gated fields — the fields that viewer may see, a gated one nullable, the rest as the class ──

interface ProductForStaff : Keyed {
    val vendor: Ref<Vendor>
    val name: String
    val price: BigDecimal
    val cost: BigDecimal?
    val margin: BigDecimal?
    val marginAlerts: List<Ref<MarginAlert>>
    val isThinMargin: Boolean
}

interface ThinMarginForStaff : Keyed {
    val vendor: Ref<Vendor>
    val name: String
    val price: BigDecimal
    val cost: BigDecimal?
    val margin: BigDecimal?
    val marginAlerts: List<Ref<MarginAlert>>
}

// ── the builder's vocabulary: one field handle per member, memberships per refinement ──

class StaffFields(path: List<String> = emptyList()) : Fields(path) {
    val name: TextField get() = TextField(fieldPath + "name")
    val role: TextField get() = TextField(fieldPath + "role")
    fun isAdministrator(): Expr = isA("Administrator")
}

class VendorAssignmentFields(path: List<String> = emptyList()) : Fields(path) {
    val staff: StaffFields get() = StaffFields(fieldPath + "staff")
    val vendor: VendorFields get() = VendorFields(fieldPath + "vendor")
}

class VendorFields(path: List<String> = emptyList()) : Fields(path) {
    val name: TextField get() = TextField(fieldPath + "name")
}

class ProductFields(path: List<String> = emptyList()) : Fields(path) {
    val vendor: VendorFields get() = VendorFields(fieldPath + "vendor")
    val name: TextField get() = TextField(fieldPath + "name")
    val price: NumField get() = NumField(fieldPath + "price")
    val cost: NumField get() = NumField(fieldPath + "cost")
    val margin: NumField get() = NumField(fieldPath + "margin")
    fun isThinMargin(): Expr = isA("ThinMargin")
}

class MarginAlertFields(path: List<String> = emptyList()) : Fields(path) {
    val product: ProductFields get() = ProductFields(fieldPath + "product")
    val raisedOn: DateTimeField get() = DateTimeField(fieldPath + "raisedOn")
}

class AdministratorFields(path: List<String> = emptyList()) : Fields(path) {
    val name: TextField get() = TextField(fieldPath + "name")
    val role: TextField get() = TextField(fieldPath + "role")
}

class ThinMarginFields(path: List<String> = emptyList()) : Fields(path) {
    val vendor: VendorFields get() = VendorFields(fieldPath + "vendor")
    val name: TextField get() = TextField(fieldPath + "name")
    val price: NumField get() = NumField(fieldPath + "price")
    val cost: NumField get() = NumField(fieldPath + "cost")
    val margin: NumField get() = NumField(fieldPath + "margin")
}

